using namespace std;
/*<===LINE==#17#===>*/
template <class T,class L> T& smax(T &x,L y){if(y>x)x=y;return x;}
template <class T,class L> T& smin(T &x,L y){if(y<x)x=y;return x;}
typedef pair<int,int> pii;
const int maxn=2e5+17;
unordered_map<int,int>mp;
int numof(int x){
  int ans=0;
  while(x)
    ans++,x/=10;
  return ans;
}
int nxt(int x){
  int ans[17],p=0;
  while(x)
    ans[p++]=(x%10)-(x<0?-1:1),x/=10;
