  while(x>=10)
    x/=10;
  return x;
}
int del(int x){
  int ans[17],p=0;
  while(x>=10)
    ans[p++]=(x%10),x/=10;
  int res=0;
  while(p--)
    res*=10,res+=ans[p];
  return res;
