int f(int x){
  if(x<=11)return min(13-x,x);
  if(mp[x])return mp[x];
  int n=0,t=1;
  while(t<x)
    t*=10,t++,n++;
  if(x*2>=t)
    return mp[x]=min(f(t-x)+n+1,(x/(t/10))*n+f(x%(t/10)));
  return mp[x]=(x/(t/10))*n+f(x%(t/10));
}
